<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Terms of Use – Consent Form</title>
    <style>
      /* ── Reset & base ─────────────────────────────────────────── */
      *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

      :root {
        --bg:           #0f1117;
        --surface:      #1a1d27;
        --border:       #2e3347;
        --border-focus: #6c8ef5;
        --text:         #e2e4ed;
        --text-muted:   #8b90a8;
        --accent:       #6c8ef5;
        --accent-hover: #849af7;
        --danger:       #f87171;
        --success:      #4ade80;
        --check-bg:     #6c8ef5;
        --radius:       10px;
        --transition:   0.18s ease;
      }

      html { font-size: 16px; }

      body {
        background: var(--bg);
        color: var(--text);
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
                     Helvetica, Arial, sans-serif;
        min-height: 100vh;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: 1.5rem;
      }

      /* ── Skip link ────────────────────────────────────────────── */
      .skip-link {
        position: absolute;
        top: -100%;
        left: 1rem;
        background: var(--accent);
        color: #fff;
        padding: 0.5rem 1rem;
        border-radius: var(--radius);
        font-weight: 600;
        text-decoration: none;
        z-index: 100;
        transition: top var(--transition);
      }
      .skip-link:focus { top: 1rem; }

      /* ── Card ─────────────────────────────────────────────────── */
      main {
        width: 100%;
        max-width: 440px;
      }

      .card {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 2.25rem 2rem;
      }

      /* ── Heading ──────────────────────────────────────────────── */
      h1 {
        font-size: 1.35rem;
        font-weight: 700;
        letter-spacing: -0.01em;
        color: var(--text);
        margin-bottom: 0.4rem;
      }

      .subtitle {
        font-size: 0.875rem;
        color: var(--text-muted);
        margin-bottom: 1.75rem;
        line-height: 1.5;
      }

      /* ── Required legend ──────────────────────────────────────── */
      .required-note {
        font-size: 0.78rem;
        color: var(--text-muted);
        margin-bottom: 1.5rem;
      }
      .required-note .marker {
        color: var(--danger);
        margin-right: 0.2em;
        font-weight: 700;
        aria-hidden: true; /* handled via aria-hidden span in HTML */
      }

      /* ── Form ─────────────────────────────────────────────────── */
      form { display: flex; flex-direction: column; gap: 1.5rem; }

      /* ── Form field wrapper ───────────────────────────────────── */
      .form-field {
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
      }

      /* ── Checkbox row ─────────────────────────────────────────── */
      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: 0.75rem;
      }

      /* Hide the native checkbox visually but keep it accessible */
      .checkbox-row input[type="checkbox"] {
        appearance: none;
        -webkit-appearance: none;
        flex-shrink: 0;
        width: 1.25rem;
        height: 1.25rem;
        margin-top: 0.1rem;
        border: 2px solid var(--border);
        border-radius: 5px;
        background: var(--bg);
        cursor: pointer;
        transition: border-color var(--transition), background var(--transition),
                    box-shadow var(--transition);
        position: relative;
      }

      .checkbox-row input[type="checkbox"]:checked {
        background: var(--check-bg);
        border-color: var(--check-bg);
      }

      /* Checkmark via pseudo-element */
      .checkbox-row input[type="checkbox"]:checked::after {
        content: "";
        display: block;
        position: absolute;
        top: 1px;
        left: 4px;
        width: 6px;
        height: 10px;
        border: 2px solid #fff;
        border-top: none;
        border-left: none;
        transform: rotate(42deg);
      }

      .checkbox-row input[type="checkbox"]:focus-visible {
        outline: 3px solid var(--border-focus);
        outline-offset: 3px;
      }

      .checkbox-row input[type="checkbox"][aria-invalid="true"] {
        border-color: var(--danger);
      }

      /* ── Checkbox label ───────────────────────────────────────── */
      .checkbox-row label {
        font-size: 0.9rem;
        color: var(--text);
        line-height: 1.5;
        cursor: pointer;
      }

      .checkbox-row label a {
        color: var(--accent);
        text-decoration: underline;
        text-underline-offset: 2px;
      }
      .checkbox-row label a:hover { color: var(--accent-hover); }
      .checkbox-row label a:focus-visible {
        outline: 3px solid var(--border-focus);
        outline-offset: 2px;
        border-radius: 2px;
      }

      /* Required marker in label */
      .req-marker {
        color: var(--danger);
        margin-left: 0.15em;
        font-weight: 700;
      }

      /* ── Helper & error text ──────────────────────────────────── */
      .helper-text {
        font-size: 0.8rem;
        color: var(--text-muted);
        padding-left: calc(1.25rem + 0.75rem); /* align under label */
        line-height: 1.45;
      }

      .error-text {
        font-size: 0.8rem;
        color: var(--danger);
        padding-left: calc(1.25rem + 0.75rem);
        line-height: 1.45;
        display: flex;
        align-items: center;
        gap: 0.3rem;
      }

      .error-text::before {
        content: "⚠";
        font-size: 0.75rem;
        flex-shrink: 0;
      }

      [hidden] { display: none !important; }

      /* ── Submit button ────────────────────────────────────────── */
      button[type="submit"] {
        width: 100%;
        padding: 0.75rem 1.25rem;
        background: var(--accent);
        color: #fff;
        border: none;
        border-radius: var(--radius);
        font-size: 0.95rem;
        font-weight: 600;
        cursor: pointer;
        letter-spacing: 0.01em;
        transition: background var(--transition), box-shadow var(--transition);
      }

      button[type="submit"]:hover { background: var(--accent-hover); }

      button[type="submit"]:focus-visible {
        outline: 3px solid var(--border-focus);
        outline-offset: 3px;
      }

      button[type="submit"]:active {
        background: #5a7de8;
      }

      /* ── Status message ───────────────────────────────────────── */
      .status-message {
        font-size: 0.875rem;
        font-weight: 500;
        text-align: center;
        padding: 0.65rem 1rem;
        border-radius: 8px;
      }

      .status-message.success {
        color: var(--success);
        background: rgba(74, 222, 128, 0.1);
        border: 1px solid rgba(74, 222, 128, 0.25);
      }

      /* ── Forced colors (high contrast) ───────────────────────── */
      @media (forced-colors: active) {
        .checkbox-row input[type="checkbox"] {
          forced-color-adjust: auto;
        }
      }

      /* ── Narrow viewport reflow ───────────────────────────────── */
      @media (max-width: 360px) {
        .card { padding: 1.5rem 1.1rem; }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <div class="card">
        <h1>Terms of Use</h1>
        <p class="subtitle">Please review and accept our terms before continuing.</p>

        <p class="required-note">
          <span class="marker" aria-hidden="true">*</span>
          Required field
        </p>

        <!-- aria-live region for submit status messages -->
        <div aria-live="polite" aria-atomic="true" id="form-status"></div>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <div class="checkbox-row">
              <input
                type="checkbox"
                id="agree-terms"
                name="agree-terms"
                required
                aria-describedby="agree-helper agree-error"
              />
              <label for="agree-terms">
                I have read and agree to the
                <a href="#terms" aria-label="Terms of Use (opens in same page)">Terms of Use</a>
                <span class="req-marker" aria-hidden="true">*</span>
              </label>
            </div>

            <p id="agree-helper" class="helper-text">
              You must accept the Terms of Use to create an account.
            </p>

            <p id="agree-error" class="error-text" hidden>
              Error: You must agree to the Terms of Use to continue.
            </p>
          </div>

          <button type="submit">Agree and continue</button>
        </form>
      </div>
    </main>

    <script>
      (function () {
        const form      = document.getElementById('consent-form');
        const checkbox  = document.getElementById('agree-terms');
        const errorMsg  = document.getElementById('agree-error');
        const statusEl  = document.getElementById('form-status');

        function showError() {
          errorMsg.hidden = false;
          checkbox.setAttribute('aria-invalid', 'true');
        }

        function clearError() {
          errorMsg.hidden = true;
          checkbox.removeAttribute('aria-invalid');
        }

        // Clear error as soon as the checkbox is checked
        checkbox.addEventListener('change', function () {
          if (checkbox.checked) clearError();
        });

        form.addEventListener('submit', function (event) {
          event.preventDefault();

          if (!checkbox.checked) {
            showError();
            checkbox.focus();
            return;
          }

          clearError();

          // Show success status message
          statusEl.textContent = '';          // reset to re-trigger live region
          requestAnimationFrame(function () {
            const msg = document.createElement('p');
            msg.className = 'status-message success';
            msg.textContent = '✓ Thank you! Your consent has been recorded.';
            statusEl.appendChild(msg);
          });

          form.reset();
        });
      })();
    </script>
  </body>
</html>
