        <div aria-live="polite" aria-atomic="true" id="form-status"></div>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <div class="checkbox-row">
              <input
                type="checkbox"
                id="agree-terms"
                name="agree-terms"
                required
                aria-describedby="agree-helper agree-error"
              />
              <label for="agree-terms">
                I have read and agree to the
                <a href="#terms" aria-label="Terms of Use (opens in same page)">Terms of Use</a>
                <span class="req-marker" aria-hidden="true">*</span>
              </label>
            </div>

            <p id="agree-helper" class="helper-text">
              You must accept the Terms of Use to create an account.
            </p>

            <p id="agree-error" class="error-text" hidden>
              Error: You must agree to the Terms of Use to continue.
            </p>
          </div>

          <button type="submit">Agree and continue</button>
        </form>
      </div>
    </main>

    <script>
      (function () {
        const form      = document.getElementById('consent-form');
        const checkbox  = document.getElementById('agree-terms');
        const errorMsg  = document.getElementById('agree-error');
        const statusEl  = document.getElementById('form-status');

        function showError() {
          errorMsg.hidden = false;
          checkbox.setAttribute('aria-invalid', 'true');
        }

        function clearError() {
          errorMsg.hidden = true;
          checkbox.removeAttribute('aria-invalid');
        }

        // Clear error as soon as the checkbox is checked
        checkbox.addEventListener('change', function () {
          if (checkbox.checked) clearError();
        });

        form.addEventListener('submit', function (event) {
          event.preventDefault();

          if (!checkbox.checked) {
            showError();
            checkbox.focus();
            return;
          }

          clearError();

          // Show success status message
          statusEl.textContent = '';          // reset to re-trigger live region
          requestAnimationFrame(function () {
            const msg = document.createElement('p');
            msg.className = 'status-message success';
            msg.textContent = '✓ Thank you! Your consent has been recorded.';
            statusEl.appendChild(msg);
          });

          form.reset();
        });
      })();
    </script>
